using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;

namespace TrueReplayer.Services
{
    /// <summary>
    /// The interface's language on the engine's side (plan .claude/planos/idiomas-tr3-2026-11-02.md,
    /// §3.5 and §3.6). The texts are in Strings.g.cs, generated by tools/gen-i18n.mjs from the same
    /// catalog the page uses (i18n/), each one in both languages, picked here: one system, and no file
    /// read at launch. The page comes in one build per language, wwwroot/&lt;language&gt;/, and the
    /// engine navigates to the one that matches.
    /// </summary>
    public static partial class S
    {
        /// <summary>The interface.json key, shared with the page (the tips' language before D30).</summary>
        public const string LanguageKey = "tr-language";

        /// <summary>Asks a test house to follow Windows like an install does, not to open in en-US.</summary>
        private const string TestLanguageVariable = "TRUEREPLAYER3_TEST_IDIOMA";

        /// <summary>The interface's language: "en-US" or "pt-BR". The page's folder in wwwroot has the same name.</summary>
        public static string Language { get; private set; } = "en-US";

        /// <summary>Whether the texts come out in Portuguese.</summary>
        public static bool IsPt => Language == "pt-BR";

        /// <summary>Where the language came from, for the log: the user's pick, Windows, or a test house.</summary>
        public static string Source { get; private set; } = "default";

        /// <summary>
        /// A stored pick as the app keeps it: "en-US" or "pt-BR", or null for Windows (no key). The tips'
        /// language of the builds before D30 wrote "en" for English.
        /// </summary>
        public static string? Normalize(string? stored) => stored switch
        {
            "en-US" or "en" => "en-US",
            "pt-BR" => "pt-BR",
            _ => null,
        };

        /// <summary>
        /// Sets the language from the stored pick (null: none). Without one it follows the display
        /// language of Windows — any Portuguese is pt-BR, anything else en-US — except in a test house,
        /// which opens in en-US so the scripts do not depend on this PC's Windows. True when it changed.
        /// </summary>
        public static bool Resolve(string? stored)
        {
            var before = Language;
            var pick = Normalize(stored);
            if (pick != null) { Language = pick; Source = "chosen"; }
            else if (CoexistenceGuard.Bypassed && !string.Equals(Environment.GetEnvironmentVariable(TestLanguageVariable), "windows", StringComparison.OrdinalIgnoreCase))
            {
                Language = "en-US";
                Source = "test house";
            }
            else
            {
                Language = WindowsLanguage().StartsWith("pt", StringComparison.OrdinalIgnoreCase) ? "pt-BR" : "en-US";
                Source = "Windows";
            }
            return Language != before;
        }

        // ── What the texts put in their blanks, in the interface's language ────────────────────────

        // Made on first use, and never a throw: a process that runs .NET without culture data (the test
        // probes load this dll with InvariantGlobalization) would otherwise fail on every text of S.
        private static CultureInfo? _en, _pt;
        private static CultureInfo Named(string name)
        {
            try { return CultureInfo.GetCultureInfo(name); }
            catch (CultureNotFoundException) { return CultureInfo.InvariantCulture; }
        }

        /// <summary>The interface's culture, for a number or a date inside a text (not the machine's: {date} and {time} keep that one).</summary>
        public static CultureInfo Culture => IsPt ? (_pt ??= Named("pt-BR")) : (_en ??= Named("en-US"));

        /// <summary>A count for a text, grouped as the language writes it: 1,000 / 1.000.</summary>
        public static string Num(long n) => n.ToString("N0", Culture);

        /// <summary>A number with its decimals for a text: 2.5 / 2,5.</summary>
        public static string Fixed(double value, int decimals) => value.ToString("F" + decimals, Culture);

        /// <summary>A list for a text: "a, b and c" / "a, b e c".</summary>
        public static string List(IEnumerable<string> items)
        {
            var all = items.ToList();
            if (all.Count <= 1) return all.Count == 1 ? all[0] : "";
            return string.Join(", ", all.Take(all.Count - 1)) + (IsPt ? " e " : " and ") + all[^1];
        }

        /// <summary>
        /// Why something failed, to follow a colon in a text. In English it is what .NET wrote, as it
        /// always was (it says the path); in Portuguese, the engine's own sentence for the exceptions a
        /// person meets — a file in use, access denied, a path that is not there, a full disk — and the
        /// .NET message for any other, which only it can say.
        /// </summary>
        public static string Reason(Exception ex)
        {
            if (!IsPt) return ex.Message;
            return ex switch
            {
                UnauthorizedAccessException => ErrorsAccessDenied,
                FileNotFoundException => ErrorsFileNotFound,
                DirectoryNotFoundException => ErrorsFolderNotFound,
                PathTooLongException => ErrorsPathTooLong,
                IOException io when Win32Code(io) is 32 or 33 => ErrorsFileInUse,
                IOException io when Win32Code(io) is 39 or 112 => ErrorsDiskFull,
                _ => ex.Message,
            };
        }

        /// <summary>The Win32 error an IOException carries in its HResult (0x8007xxxx), or -1.</summary>
        private static int Win32Code(IOException ex) => (ex.HResult & 0xFFFF0000) == 0x80070000 ? ex.HResult & 0xFFFF : -1;

        /// <summary>The display language Windows uses for this user (the first preferred UI language).</summary>
        public static string WindowsLanguage()
        {
            try
            {
                uint size = 0;
                if (GetUserPreferredUILanguages(MUI_LANGUAGE_NAME, out _, null, ref size) && size > 1)
                {
                    var buffer = new char[size];
                    if (GetUserPreferredUILanguages(MUI_LANGUAGE_NAME, out _, buffer, ref size))
                    {
                        // A double-null-terminated list; the first entry is the one Windows shows.
                        int end = Array.IndexOf(buffer, '\0');
                        var first = new string(buffer, 0, end >= 0 ? end : buffer.Length);
                        if (first.Length > 0) return first;
                    }
                }
            }
            catch { /* the culture below says the same on every Windows this app runs on */ }
            return CultureInfo.CurrentUICulture.Name;
        }

        private const uint MUI_LANGUAGE_NAME = 0x8;

        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool GetUserPreferredUILanguages(uint dwFlags, out uint pulNumLanguages, char[]? pwszLanguagesBuffer, ref uint pcchLanguagesBuffer);
    }
}
